arguments.command:
cat << 'EOF' > /tmp/stackalloc_nint.cs
using System;

var span = (Span<nint>)stackalloc nint[4];
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = 40;

nint sum = 0;
foreach (var val in span)
    sum += val;

Console.WriteLine($"Span length: {span.Length}");
Console.WriteLine($"Sum: {sum}");
Console.WriteLine($"nint size: {nint.Size} bytes");
EOF
dotnet run --project /dev/null 2>/dev/null || dotnet-script /tmp/stackalloc_nint.cs 2>/dev/null || (cd /tmp && dotnet new console -o stackalloc_test --force -n StackallocTest > /dev/null 2>&1 && cp stackalloc_nint.cs stackalloc_test/Program.cs && dotnet run --project stackalloc_test)

